-- YottaJourney PostgreSQL schema (PostgreSQL 15+).
-- Apply to a fresh database: psql -v ON_ERROR_STOP=1 -d yottajourney -f schema.sql
-- IDs are immutable, assigned by the application, and never generated by the database.
-- NO ACTION FKs intentionally preserve historical evidence; deactivate instead of deleting.

CREATE TABLE customers (
    customer_id VARCHAR(16) PRIMARY KEY CHECK (customer_id ~ '^CUS-[0-9]{6}$'),
    created_at TIMESTAMPTZ NOT NULL,
    consent_status VARCHAR(12) NOT NULL CHECK (consent_status IN ('granted','denied','unknown')),
    lifecycle_state VARCHAR(16) NOT NULL CHECK (lifecycle_state IN ('active','inactive','deleted')),
    country CHAR(2) CHECK (country IS NULL OR country ~ '^[A-Z]{2}$')
);

CREATE TABLE pages (
    page_id VARCHAR(16) PRIMARY KEY CHECK (page_id ~ '^PAG-[0-9]{6}$'),
    page_name TEXT NOT NULL CHECK (length(btrim(page_name)) > 0),
    page_type VARCHAR(24) NOT NULL CHECK (page_type IN ('landing','discovery','product','cart','checkout','payment','support','campaign')),
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE products (
    product_id VARCHAR(16) PRIMARY KEY CHECK (product_id ~ '^PRD-[0-9]{6}$'),
    product_name TEXT NOT NULL CHECK (length(btrim(product_name)) > 0),
    category TEXT NOT NULL CHECK (length(btrim(category)) > 0),
    unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0),
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE experiments (
    experiment_id VARCHAR(16) PRIMARY KEY CHECK (experiment_id ~ '^EXP-[0-9]{4}-[0-9]{6}$'),
    name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
    status VARCHAR(16) NOT NULL CHECK (status IN ('draft','active','completed','paused')),
    start_at TIMESTAMPTZ NOT NULL,
    end_at TIMESTAMPTZ NOT NULL,
    CHECK (end_at >= start_at)
);

CREATE TABLE sessions (
    session_id VARCHAR(20) PRIMARY KEY CHECK (session_id ~ '^SES-[0-9]{4}-[0-9]{6}$'),
    customer_id VARCHAR(16) REFERENCES customers(customer_id),
    anonymous_id VARCHAR(24) NOT NULL CHECK (length(btrim(anonymous_id)) > 0),
    started_at TIMESTAMPTZ NOT NULL,
    ended_at TIMESTAMPTZ,
    channel VARCHAR(16) NOT NULL CHECK (channel IN ('website','mobile_app')),
    device_type VARCHAR(16) NOT NULL CHECK (device_type IN ('desktop','mobile','tablet')),
    consent_status VARCHAR(12) NOT NULL CHECK (consent_status IN ('granted','denied','unknown')),
    is_bot BOOLEAN NOT NULL DEFAULT FALSE,
    lifecycle_state VARCHAR(16) NOT NULL CHECK (lifecycle_state IN ('active','completed','expired')),
    CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE TABLE journey_events (
    event_id VARCHAR(64) PRIMARY KEY CHECK (event_id ~ '^EVT-SES-[0-9]{4}-[0-9]{6}-[0-9]{6}$'),
    session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id),
    customer_id VARCHAR(16) REFERENCES customers(customer_id),
    anonymous_id VARCHAR(24) NOT NULL CHECK (length(btrim(anonymous_id)) > 0),
    event_type VARCHAR(40) NOT NULL CHECK (event_type IN ('session_started','page_viewed','product_viewed','added_to_cart','checkout_started','payment_attempted','purchase_completed','purchase_failed','support_contacted')),
    event_timestamp TIMESTAMPTZ NOT NULL,
    ingestion_timestamp TIMESTAMPTZ NOT NULL,
    channel VARCHAR(16) NOT NULL CHECK (channel IN ('website','mobile_app')),
    page_id VARCHAR(16) REFERENCES pages(page_id),
    product_id VARCHAR(16) REFERENCES products(product_id),
    event_properties JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(event_properties) = 'object'),
    event_version VARCHAR(12) NOT NULL CHECK (length(btrim(event_version)) > 0),
    CHECK (ingestion_timestamp >= event_timestamp)
);

CREATE TABLE carts (
    cart_id VARCHAR(20) PRIMARY KEY CHECK (cart_id ~ '^CRT-[0-9]{6}$'),
    session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id),
    customer_id VARCHAR(16) REFERENCES customers(customer_id),
    created_at TIMESTAMPTZ NOT NULL,
    state VARCHAR(16) NOT NULL CHECK (state IN ('open','abandoned','converted','expired'))
);

CREATE TABLE cart_items (
    cart_item_id VARCHAR(20) PRIMARY KEY CHECK (cart_item_id ~ '^CIT-[0-9]{6}$'),
    cart_id VARCHAR(20) NOT NULL REFERENCES carts(cart_id),
    product_id VARCHAR(16) NOT NULL REFERENCES products(product_id),
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0),
    CONSTRAINT cart_items_cart_product_uq UNIQUE (cart_id, product_id)
);

CREATE TABLE orders (
    order_id VARCHAR(20) PRIMARY KEY CHECK (order_id ~ '^ORD-[0-9]{6}$'),
    session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id),
    customer_id VARCHAR(16) REFERENCES customers(customer_id),
    cart_id VARCHAR(20) REFERENCES carts(cart_id),
    ordered_at TIMESTAMPTZ NOT NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('pending','paid','failed','refunded')),
    total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0),
    currency CHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$')
);

CREATE TABLE support_tickets (
    ticket_id VARCHAR(20) PRIMARY KEY CHECK (ticket_id ~ '^SUP-[0-9]{6}$'),
    session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id),
    customer_id VARCHAR(16) REFERENCES customers(customer_id),
    created_at TIMESTAMPTZ NOT NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('open','pending','resolved','closed')),
    reason TEXT NOT NULL CHECK (length(btrim(reason)) > 0)
);

CREATE TABLE experiment_assignments (
    assignment_id VARCHAR(20) PRIMARY KEY CHECK (assignment_id ~ '^ASN-[0-9]{6}$'),
    experiment_id VARCHAR(16) NOT NULL REFERENCES experiments(experiment_id),
    session_id VARCHAR(20) NOT NULL REFERENCES sessions(session_id),
    variant VARCHAR(32) NOT NULL CHECK (length(btrim(variant)) > 0),
    assigned_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT experiment_assignments_experiment_session_uq UNIQUE (experiment_id, session_id)
);

CREATE TABLE journey_outcomes (
    outcome_id VARCHAR(32) PRIMARY KEY CHECK (outcome_id ~ '^OUT-SES-[0-9]{4}-[0-9]{6}$'),
    session_id VARCHAR(20) NOT NULL UNIQUE REFERENCES sessions(session_id),
    outcome_type VARCHAR(32) NOT NULL CHECK (outcome_type IN ('converted','checkout_abandoned','cart_abandoned','browsed','bot')),
    outcome_at TIMESTAMPTZ NOT NULL,
    rule_version VARCHAR(12) NOT NULL CHECK (length(btrim(rule_version)) > 0)
);

-- FK/query indexes (PK and UNIQUE constraints create their own indexes).
CREATE INDEX sessions_customer_started_idx ON sessions(customer_id, started_at DESC);
CREATE INDEX sessions_channel_device_started_idx ON sessions(channel, device_type, started_at DESC);
CREATE INDEX sessions_anonymous_started_idx ON sessions(anonymous_id, started_at DESC);
CREATE INDEX sessions_consent_idx ON sessions(consent_status, started_at DESC);

CREATE INDEX journey_events_session_time_idx ON journey_events(session_id, event_timestamp, event_id);
CREATE INDEX journey_events_ingestion_idx ON journey_events(ingestion_timestamp);
CREATE INDEX journey_events_type_time_idx ON journey_events(event_type, event_timestamp DESC);
CREATE INDEX journey_events_customer_time_idx ON journey_events(customer_id, event_timestamp DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX journey_events_page_time_idx ON journey_events(page_id, event_timestamp DESC) WHERE page_id IS NOT NULL;
CREATE INDEX journey_events_product_time_idx ON journey_events(product_id, event_timestamp DESC) WHERE product_id IS NOT NULL;
CREATE INDEX journey_events_channel_time_idx ON journey_events(channel, event_timestamp DESC);
CREATE INDEX journey_events_properties_gin_idx ON journey_events USING GIN(event_properties);

CREATE INDEX carts_session_created_idx ON carts(session_id, created_at DESC);
CREATE INDEX carts_customer_created_idx ON carts(customer_id, created_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX carts_state_created_idx ON carts(state, created_at DESC);
CREATE INDEX cart_items_product_idx ON cart_items(product_id);

CREATE INDEX orders_session_time_idx ON orders(session_id, ordered_at DESC);
CREATE INDEX orders_customer_time_idx ON orders(customer_id, ordered_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX orders_cart_idx ON orders(cart_id) WHERE cart_id IS NOT NULL;
CREATE INDEX orders_status_time_idx ON orders(status, ordered_at DESC);

CREATE INDEX support_tickets_session_created_idx ON support_tickets(session_id, created_at DESC);
CREATE INDEX support_tickets_customer_created_idx ON support_tickets(customer_id, created_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX support_tickets_status_created_idx ON support_tickets(status, created_at DESC);

CREATE INDEX experiments_status_effective_idx ON experiments(status, start_at, end_at);
CREATE INDEX experiment_assignments_session_time_idx ON experiment_assignments(session_id, assigned_at DESC);
CREATE INDEX experiment_assignments_experiment_variant_idx ON experiment_assignments(experiment_id, variant);
CREATE INDEX journey_outcomes_type_time_idx ON journey_outcomes(outcome_type, outcome_at DESC);

-- Useful integrity/reconciliation queries; these are intentionally not enforced as row CHECKs.
CREATE VIEW cart_order_reconciliation AS
SELECT c.cart_id,
       COALESCE(SUM(ci.quantity * ci.unit_price), 0)::NUMERIC(12,2) AS cart_subtotal,
       o.order_id,
       o.total_amount AS order_total,
       CASE WHEN o.order_id IS NULL THEN NULL
            ELSE o.total_amount - COALESCE(SUM(ci.quantity * ci.unit_price), 0)
       END::NUMERIC(12,2) AS total_difference
FROM carts AS c
LEFT JOIN cart_items AS ci ON ci.cart_id = c.cart_id
LEFT JOIN orders AS o ON o.cart_id = c.cart_id
GROUP BY c.cart_id, o.order_id, o.total_amount;

CREATE VIEW session_identity_exceptions AS
SELECT s.session_id, s.customer_id AS session_customer_id,
       s.consent_status AS session_consent_status,
       e.event_id, e.customer_id AS event_customer_id
FROM sessions AS s
JOIN journey_events AS e ON e.session_id = s.session_id
WHERE (s.consent_status <> 'granted' AND (s.customer_id IS NOT NULL OR e.customer_id IS NOT NULL))
   OR (s.customer_id IS NOT NULL AND e.customer_id IS NOT NULL AND s.customer_id <> e.customer_id);
